(()=>{
const T=Ember3D,button=document.createElement('button');button.id='create-particle-mesh';button.textContent='Create a mesh…';$('#import-particle-mesh').after(button);
let renderer,geometry,material,controls,frame,observer;
function cleanup(){cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();geometry?.dispose();material?.dispose();renderer?.dispose();renderer=null;}
$('#dialog').addEventListener('close',cleanup);
button.onclick=()=>{
 cleanup();dialog('<div class="eyebrow">SMALL MESH CREATOR</div><h2>Make a particle shape</h2><p>Start with a shape, then stretch, taper or twist it. Drag to turn the preview; scroll to zoom.</p><div id="mesh-preview" style="height:260px;background:#11121a;border-radius:12px;overflow:hidden"></div><label>Shape<select id="mesh-shape"><option value="sphere">Sphere</option><option value="box">Cube</option><option value="cone">Cone / spike</option><option value="cylinder">Cylinder</option><option value="torus">Ring</option><option value="crystal">Crystal</option><option value="plane">Plane / shard</option></select></label><div id="mesh-sliders"></div><label class="switch-label">Wireframe preview<input id="mesh-wire" type="checkbox"></label><p id="mesh-info" role="status"></p><button id="mesh-use" class="primary">Use on active layer</button><button id="mesh-download">Save mesh as GLB</button><p>Use replaces only the active layer’s particle shape. Size controls its proportions; particle size controls its size in the effect. Saving a GLB works without Blender. Using it as a particle on Windows requires Blender for the Unreal-ready mesh conversion.</p>');
 const values={width:1,height:1,depth:1,taper:0,twist:0,detail:16};
 for(const [key,label,min,max,step] of [['width','Width',.1,4,.1],['height','Height',.1,4,.1],['depth','Depth',.1,4,.1],['taper','Taper toward top',0,.95,.05],['twist','Twist (degrees)',-180,180,5],['detail','Roundness / detail',4,32,1]]){const row=document.createElement('label');row.innerHTML=label+' <output></output><input type="range" id="mesh-'+key+'" min="'+min+'" max="'+max+'" step="'+step+'" value="'+values[key]+'">';$('#mesh-sliders').append(row);row.querySelector('output').textContent=values[key];row.querySelector('input').oninput=e=>{values[key]=Number(e.target.value);row.querySelector('output').textContent=values[key];rebuild();};}
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(40,1,.01,100);camera.position.set(3,2,4);renderer=new T.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));$('#mesh-preview').append(renderer.domElement);controls=new T.OrbitControls(camera,renderer.domElement);material=new T.MeshNormalMaterial({side:T.DoubleSide});const mesh=new T.Mesh(undefined,material);scene.add(mesh);
 function rebuild(){geometry?.dispose();const n=Math.round(values.detail),shape=$('#mesh-shape').value;geometry=shape==='box'?new T.BoxGeometry(1,1,1,4,12,4):shape==='cone'?new T.ConeGeometry(.6,1.5,n,12):shape==='cylinder'?new T.CylinderGeometry(.5,.5,1.5,n,12):shape==='torus'?new T.TorusGeometry(.6,.18,8,n):shape==='crystal'?new T.OctahedronGeometry(.9,0):shape==='plane'?new T.PlaneGeometry(1,1.5,4,12):new T.SphereGeometry(.7,n,Math.max(4,n/2));const p=geometry.attributes.position;geometry.computeBoundingBox();const bottom=geometry.boundingBox.min.y,span=geometry.boundingBox.max.y-bottom;for(let i=0;i<p.count;i++){const y=p.getY(i),t=span?(y-bottom)/span:0,a=values.twist*Math.PI/180*t,shrink=1-values.taper*t,x=p.getX(i)*shrink,z=p.getZ(i)*shrink;p.setXYZ(i,(x*Math.cos(a)-z*Math.sin(a))*values.width,y*values.height,(x*Math.sin(a)+z*Math.cos(a))*values.depth);}geometry.computeVertexNormals();mesh.geometry=geometry;$('#mesh-info').textContent=Math.round((geometry.index?.count||p.count)/3)+' triangles · Preview shading only; particles use the layer’s color and glow.';}
 $('#mesh-shape').onchange=rebuild;$('#mesh-wire').onchange=e=>material.wireframe=e.target.checked;
 observer=new ResizeObserver(()=>{const host=$('#mesh-preview');if(!renderer||!host)return;renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();});observer.observe($('#mesh-preview'));
 function tick(){if(!renderer)return;controls.update();renderer.render(scene,camera);frame=requestAnimationFrame(tick);}rebuild();tick();
 async function exportMesh(){const obj=new T.Mesh(geometry.clone(),new T.MeshStandardMaterial({color:0xffffff,side:T.DoubleSide}));try{return await new T.GLTFExporter().parseAsync(obj,{binary:true});}finally{obj.geometry.dispose();obj.material.dispose();}}
 $('#mesh-download').onclick=async()=>{try{const buffer=await exportMesh();if(window.emberSaveMeshBlob){const r=await window.emberSaveMeshBlob(new Blob([buffer],{type:'model/gltf-binary'}),'Ember-'+$('#mesh-shape').value+'.glb');if(!r.ok)throw Error(r.error);if(!r.canceled)toast('Mesh saved');return;}const url=URL.createObjectURL(new Blob([buffer],{type:'model/gltf-binary'})),a=document.createElement('a');a.href=url;a.download='Ember-'+$('#mesh-shape').value+'.glb';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){toast(e.message);}};
 $('#mesh-use').disabled=!window.emberDesktop?.createParticleMesh;
 $('#mesh-use').onclick=async()=>{const target=layers[activeLayer],apply=$('#mesh-use');apply.disabled=true;$('#mesh-info').textContent='Preparing mesh…';try{const buffer=await exportMesh(),bytes=new Uint8Array(buffer);let text='';for(const byte of bytes)text+=String.fromCharCode(byte);const r=await window.emberDesktop.createParticleMesh(btoa(text));if(!r.ok)throw Error(r.error);await prepareMesh(r.mesh);if(!layers.includes(target))throw Error('The layer was removed. Reopen the mesh creator.');const effect=target===layers[activeLayer]?state:target.effect;effect.renderer='mesh';effect.meshRef=r.mesh.id;effect.meshAsset='';target.effect=effect;if(target===layers[activeLayer])state=effect;sync();persist();$('#dialog').close();toast('Mesh added to the active layer');}catch(e){if($('#mesh-info'))$('#mesh-info').textContent=e.message;}finally{apply.disabled=false;}};
};
})();
